    const title = document.createElement('h2');
    title.textContent = 'Age Detail Calculations';
    title.style.color = CHC_TEXT_PRIMARY;
    const description = document.createElement('p');
    description.innerHTML = 'The editor shows calculated age ranges and birth dates based on the considered date.<br>Open the modal to see live calculations as you change the category.';
    description.style.color = CHC_TEXT_SECONDARY;
    description.style.marginBottom = '1.5em';
