  const fixture = seededDraw({
    drawSize: 16,
    seedsCount: 4
  });
  const {
    series,
    scaleName
  } = buildPressureSeries({
    matchUps: fixture.matchUps
  });
  const wrapper = panel('The top seed — what good seeding looks like', 'Seeding exists to give the strongest player the easiest early road. That reads here as a curve well below the even line that climbs toward the final as the possible opponents get stronger.');
  // Same domain as the UnseededPath story so the two can be read against each
  // other — the comparison the caption invites is only honest if the scales match.
  buildPressureChart(wrapper, pick(series, fixture.topSeedId), {
    scaleName,
    yDomain: sharedYDomain(series)
  });
  return wrapper;
