  render: ({
    ...args
  }) => {
    const {
      composition: base,
      matchUps,
      context
    } = buildStructureView(args);
    const composition: any = {
      ...base,
      configuration: {
        ...base.configuration,
        roundHeader: true
      }
    };
    const content = renderStructure({
      carousel: {
        peek: args.peek
      },
      matchUps: matchUps as any,
      eventHandlers,
      composition,
      context
    });
    const pager = renderRoundPager({
      structure: content
    });
    const phone = document.createElement('div');
    phone.style.cssText = 'width: 375px; display: flex; flex-direction: column; gap: 0.5rem;';
    phone.append(pager.element, renderContainer({
      theme: composition.theme,
      content
    }));
    return phone;
  }
